idx.write("""<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ALE TV KE LIVE</title>
<style>*{margin:0;padding:0;box-sizing:border-box}body{background:#000;color:#fff;font-family:sans-serif}header{background:#0f1a0f;padding:12px 15px;display:flex;justify-content:space-between;position:sticky;top:0;z-index:50}#playerWrap{position:sticky;top:45px;z-index:40;background:#000;width:100%;aspect-ratio:16/9}#player{width:100%;height:100%;background:#000;position:relative}#player iframe{width:100%;height:100%;border:0;position:absolute;top:0;left:0}.info{padding:15px;background:#0a0a0a}.btn-join{background:#00ff88;color:#000;border:none;padding:14px;width:100%;border-radius:25px;font-weight:900;margin-top:12px}</style></head><body>
<header><b>ALE TV KE LIVE</b><span style="color:#00ff88;font-size:12px">TILL 3624692</span></header>
<div id="playerWrap"><div id="player"><div id="msg" style="color:#888;text-align:center;padding:40px">📺 Hakuna video - Nenda Admin weka YouTube link</div><iframe id="yt" style="display:none" allowfullscreen allow="autoplay; encrypted-media"></iframe></div></div>
<div class="info"><h2 id="title">Karibu ALE TV</h2><div id="nowPlaying" style="font-size:12px;opacity:.7;margin-top:5px">System mpya - haikatiki</div></div>
<script>
function getYtId(url){if(!url)return'';url=url.trim();if(url.includes('youtu.be/'))return url.split('youtu.be/')[1].split('?')[0].split('&')[0];try{let u=new URL(url);if(u.searchParams.get('v'))return u.searchParams.get('v');}catch(e){let m=url.match(/v=([^&]+)/);if(m)return m[1];}return'';}
function loadTV(){let cur=null;try{cur=JSON.parse(localStorage.getItem('aletv_live_now')||'null')}catch{}let state=null;try{state=JSON.parse(localStorage.getItem('aletv_state_v2')||'null')}catch{}if(!cur&&state&&state.playlist&&state.playlist.length>0)cur=state.playlist.find(p=>p.status==='now')||state.playlist[0];let msg=document.getElementById('msg'),yt=document.getElementById('yt');if(!cur){msg.innerHTML='📺 Hakuna video<br><span style="font-size:11px">Nenda Admin: localhost:8081/admin.html</span>';msg.style.display='block';yt.style.display='none';return;}document.getElementById('title').innerText=cur.title;document.getElementById('nowPlaying').innerText=cur.title;let id=cur.ytid||getYtId(cur.url);if(!id){msg.innerHTML='⚠️ Link sio sahihi';msg.style.display='block';yt.style.display='none';return;}msg.style.display='none';yt.src='https://www.youtube.com/embed/'+id+'?autoplay=1&playsinline=1&rel=0&modestbranding=1';yt.style.display='block';}
loadTV();setInterval(loadTV,3000);
</script></body></html>""")
